INSERT INTO categorias (nombre, descripcion) VALUES ('Electrónica', 'Dispositivos electrónicos');
INSERT INTO categorias (nombre, descripcion) VALUES ('Ropa', 'Prendas de vestir');
INSERT INTO categorias (nombre) VALUES ('Hogar');

-- Los ids serán 1, 2, 3 automáticamente
```

