```sql
CREATE TABLE categorias (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50) NOT NULL
);

CREATE TABLE productos (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(100) NOT NULL,
  id_categoria INT,
  FOREIGN KEY (id_categoria)
    REFERENCES categorias(id)
    ON DELETE CASCADE
);

INSERT INTO categorias (nombre) VALUES ('Electrónica');
INSERT INTO productos (nombre, id_categoria) VALUES ('Laptop', 1), ('Móvil', 1), ('Tablet', 1);

-- Borrar la categoría
DELETE FROM categorias WHERE id = 1;

-- Verificar: los 3 productos también se borraron
SELECT * FROM productos;
-- Resultado vacío
```

```sql
CREATE TABLE profesores (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50) NOT NULL
);

CREATE TABLE asignaturas (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(100) NOT NULL,
  id_profesor INT,
  FOREIGN KEY (id_profesor)
    REFERENCES profesores(id)
    ON DELETE SET NULL
);

INSERT INTO profesores (nombre) VALUES ('Prof. García');
INSERT INTO asignaturas (nombre, id_profesor) VALUES ('SQL', 1), ('Java', 1);

-- Borrar el profesor
DELETE FROM profesores WHERE id = 1;

-- Verificar: las asignaturas siguen, pero sin profesor
SELECT * FROM asignaturas;
-- 1 | SQL | NULL
-- 2 | Java | NULL
```

```sql
CREATE TABLE alumnos (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50) NOT NULL
);

CREATE TABLE notas (
  id INT PRIMARY KEY AUTO_INCREMENT,
  id_alumno INT NOT NULL,
  nota DECIMAL(4,2) NOT NULL,
  FOREIGN KEY (id_alumno)
    REFERENCES alumnos(id)
    ON DELETE RESTRICT
);

INSERT INTO alumnos (nombre) VALUES ('Juan');
INSERT INTO notas (id_alumno, nota) VALUES (1, 8.5);

-- Intentar borrar el alumno
DELETE FROM alumnos WHERE id = 1;
-- Error: Cannot delete or update a parent row: a foreign key constraint fails

-- Solución: borrar primero las notas
DELETE FROM notas WHERE id_alumno = 1;
DELETE FROM alumnos WHERE id = 1; -- Ahora sí funciona
```

**Explicación**: RESTRICT impide borrar el padre si existen hijos. Es una protección contra borrados accidentales.

