```sql
-- Eliminar temp_data si existe
DROP TABLE IF EXISTS temp_data;

-- Para eliminar productos (que tiene FK a categorías):
-- Opción 1: Eliminar primero la FK, luego la tabla
ALTER TABLE productos DROP FOREIGN KEY fk_producto_categoria;
DROP TABLE productos;

-- Opción 2: Eliminar la tabla dependiente primero
DROP TABLE IF EXISTS productos;

-- Opción 3: Usar CASCADE (MySQL 8+)
DROP TABLE IF EXISTS productos CASCADE;
```

```sql
CREATE TABLE prueba (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50)
);

INSERT INTO prueba (nombre) VALUES ('A'), ('B'), ('C'), ('D'), ('E');
-- ids: 1, 2, 3, 4, 5

TRUNCATE TABLE prueba;

INSERT INTO prueba (nombre) VALUES ('X'), ('Y'), ('Z');
-- ids: 1, 2, 3 (se reseteó el AUTO_INCREMENT)

-- Si hubiéramos usado DELETE FROM prueba;
-- y luego insertáramos X, Y, Z → los ids serían 6, 7, 8
```

**Diferencia**: TRUNCATE resetea el AUTO_INCREMENT a 1. DELETE lo mantiene donde estaba.

