```sql
-- 1. Crear base de datos
CREATE DATABASE IF NOT EXISTS tienda_online
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE tienda_online;

-- 2. Crear tablas
CREATE TABLE categorias (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50) NOT NULL UNIQUE,
  descripcion TEXT
);

CREATE TABLE productos (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(150) NOT NULL,
  precio DECIMAL(10,2) NOT NULL CHECK (precio > 0),
  stock INT NOT NULL DEFAULT 0 CHECK (stock >= 0),
  id_categoria INT,
  CONSTRAINT fk_producto_categoria
    FOREIGN KEY (id_categoria) REFERENCES categorias(id)
    ON DELETE SET NULL ON UPDATE CASCADE
);

CREATE TABLE clientes (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(50) NOT NULL,
  email VARCHAR(100) NOT NULL UNIQUE,
  telefono VARCHAR(20),
  fecha_registro DATE DEFAULT (CURRENT_DATE)
);

CREATE TABLE pedidos (
  id INT PRIMARY KEY AUTO_INCREMENT,
  id_cliente INT NOT NULL,
  fecha DATE DEFAULT (CURRENT_DATE),
  estado ENUM('pendiente', 'procesado', 'enviado', 'entregado') DEFAULT 'pendiente',
  CONSTRAINT fk_pedido_cliente
    FOREIGN KEY (id_cliente) REFERENCES clientes(id)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

CREATE TABLE lineas_pedido (
  id_pedido INT,
  id_producto INT,
  cantidad INT NOT NULL DEFAULT 1 CHECK (cantidad > 0),
  precio_unitario DECIMAL(10,2) NOT NULL CHECK (precio_unitario > 0),
  PRIMARY KEY (id_pedido, id_producto),
  CONSTRAINT fk_linea_pedido
    FOREIGN KEY (id_pedido) REFERENCES pedidos(id)
    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_linea_producto
    FOREIGN KEY (id_producto) REFERENCES productos(id)
    ON DELETE RESTRICT ON UPDATE CASCADE
);

-- 3. Insertar datos
INSERT INTO categorias (nombre) VALUES ('Electrónica'), ('Ropa'), ('Hogar');
INSERT INTO productos (nombre, precio, stock, id_categoria) VALUES
('Laptop', 899.99, 10, 1),
('Camiseta', 19.99, 50, 2),
('Lámpara', 34.99, 25, 3);
INSERT INTO clientes (nombre, email) VALUES
('Juan García', 'juan@email.com'),
('María López', 'maria@email.com'),
('Pedro Sánchez', 'pedro@email.com');
INSERT INTO pedidos (id_cliente) VALUES (1), (2), (1);
INSERT INTO lineas_pedido VALUES (1, 1, 1, 899.99), (1, 2, 2, 19.99), (2, 3, 1, 34.99);

-- 4. Verificar
DESCRIBE categorias;
DESCRIBE productos;
DESCRIBE clientes;
DESCRIBE pedidos;
DESCRIBE lineas_pedido;
```
